model = SentenceTransformer('all-MiniLM-L6-v2')

humanList = []
aiList = []
for content in dataJson["contents"]:
    humanList.append(content["human"])
    aiList.append(content["AI"])

print(f"Total length: {len(humanList)}")

simScores = np.empty((len(humanList), len(humanList)))
levenScores = np.empty((len(humanList), len(humanList)))

for currIndex in range(len(humanList)):
    for baseIndex in range(len(humanList)):
        baseStr = humanList[baseIndex]
        baseVC = model.encode([baseStr])[0]

        targetStr = humanList[currIndex]
        if baseIndex <= currIndex:
            targetStr = aiList[currIndex]
        targetVC = model.encode([targetStr])[0]

        similarityScore = 1 - distance.cosine(targetVC, baseVC)
        simScores[currIndex][baseIndex] = similarityScore

        levenScore = Levenshtein.distance(baseStr.lower(), targetStr.lower()) / max(len(baseStr), len(targetStr))
        levenScores[currIndex][baseIndex] = levenScore

simScores = np.round(simScores, decimals=3)
levenScores = np.round(levenScores, decimals=3)
# print(simScores)
print(levenScores)



